c4 = open(S + '/rerun/out_C4_r2.txt').read(); c6 = open(S + '/rerun/out_C6_r3.txt').read()
grid = {(m.group(1), m.group(3)): m.group(4) for m in re.finditer(r'GRID (\S+)\s+(ARM-CELL)\s+(\S+)\s+-> (\S+)', c6)}
cost_rows = set(); row = None
for ln in c4.splitlines():
    m = re.match(r'ROW (\S+) ', ln)
    if m: row = m.group(1)
    m = re.match(r'\s+LANE (OPEN_N\d+) c=\d+ n=\d+ m=\d+ g=\d+ regime_ratio=[\d.]+ kappa', ln)
    if m and row: cost_rows.add((row, m.group(1)))
def g_min(m):
    if m == 1: return 1
    return 2 ** (m - 1) if m < 13 else 2 ** (m - 1) - 1
def verdict(name, role, lane):
    gm = g_min(lane['m_span'])
    return R.cell_verdict({'n': lane['n'], 'collapsed': lane['collapsed'], 'l_coprime_def_field_order': lane['l_coprime_def_field_order'],
                           'g_min': gm, 'cond7': lane['cond7'], 'regime_ratio': gm / lane['c'], 'cost_available': (name, role) in cost_rows})
agree = disagree = 0
for section in ('rows', 'prime_controls'):
    for name, rr in census[section].items():
        for role, lane in rr['lanes'].items():
            v = verdict(name, role, lane); gv = grid.get((name, role))
            agree += v == gv; disagree += v != gv
            if v != gv: print('DIFF', name, role, 'recipe', v, 'grid', gv)
print('ARM-CELL prose recipe on frozen census vs C-6 GRID planted verdicts: agree', agree, 'disagree', disagree)
